// ══════════════════════════════════════════════════════════════════
//  Upstream Registry — pulse layer ↔ taipei-gis-analytics catalog dataset
// ══════════════════════════════════════════════════════════════════
//
// Generated by scripts/audit/06_apply_to_pulse.py from match_final.csv.
// SSOT for upstream data sources is taipei-gis-analytics/docs/data-catalog/
// This file is the bridge: layer_key → catalog dataset_id.
//
// Status values:
//   verified         — bridged to one or more catalog datasets
//   pulse_only       — pure-frontend layer (derived / animated / no upstream)
//   catalog_missing  — needs new entry in catalog before bridging

import type { LayerVisibility } from '../types';

export type UpstreamStatus = 'verified' | 'pulse_only' | 'catalog_missing';
export type UpstreamConfidence = 'HIGH' | 'MED' | 'LOW';

export interface UpstreamDataset {
  /** catalog dataset_id (matches frontmatter in taipei-gis-analytics/docs/data-catalog/<theme>/<dataset_id>.md) */
  datasetId: string;
  /** match confidence — HIGH = explicit frontend_target / exact name; MED = normalized variant; LOW = fuzzy */
  confidence: UpstreamConfidence;
}

export interface UpstreamRef {
  status: UpstreamStatus;
  /** Primary catalog dataset (empty array for pulse_only / catalog_missing) */
  datasets: UpstreamDataset[];
  /** For status='pulse_only': which other layer_keys / datasets this is derived from */
  derivedFrom?: string[];
  /** For status='pulse_only': short description of how the data is generated/processed */
  processing?: string;
  /** Free-form reason when status != 'verified' */
  note?: string;
}

