// ── Convenience helpers ──

export function getUpstreamFor(layerKey: keyof LayerVisibility): UpstreamRef {
  return UPSTREAM_REGISTRY[layerKey];
}

export function getAllVerifiedDatasets(): Set<string> {
  const out = new Set<string>();
  for (const ref of Object.values(UPSTREAM_REGISTRY)) {
    if (ref.status === 'verified') {
      for (const d of ref.datasets) out.add(d.datasetId);
    }
  }
  return out;
}
